$_MODULE['<{vatnumber}prestashop>vatnumber_a23a7e78097683f4826b5be2d3250509'] = 'Hintergrundpruefung';
$_MODULE['<{vatnumber}prestashop>vatnumber_f9aa2021e9745496a3e31363891084e8'] = 'Geschaeftskunden in einem anderen EU-Land zahlen keine MwSt., wenn sie eine gueltige USt-IdNr. angeben (Reverse-Charge-Verfahren). Der Kunde traegt die Nummer in seiner Adresse ein, das Modul prueft sie (erst lokal, dann bei VIES, der offiziellen EU-Datenbank), und Preise, Warenkorb und Rechnungen fuer diesen Kunden wechseln auf 0% MwSt.';
$_MODULE['<{vatnumber}prestashop>vatnumber_060bf2d587991d8f090a1309b285291c'] = 'Pruefen';
$_MODULE['<{vatnumber}prestashop>vatnumber_a9acaef07315f1610afd59b2a10ec4cc'] = 'USt-IdNr. automatisch pruefen';
$_MODULE['<{vatnumber}prestashop>vatnumber_c2c74b135cab679a815e04b2a9d5eec0'] = 'Bestaetigte Nummern werden 30 Tage aus dem lokalen Cache bedient und alle 180 Tage neu geprueft, da USt-Registrierungen ablaufen koennen.';
$_MODULE['<{vatnumber}prestashop>vatnumber_d55032733add57a402d67e096c0bbd38'] = 'USt-Status konnte nicht angezeigt werden: %s';
$_MODULE['<{vatnumber}prestashop>vatnumber_f557912d9b773f3b62ab61d7239e69ec'] = 'Kunden aus dem eigenen Land zahlen immer MwSt. Leerzeichen und Punkte in der Nummer sind kein Problem, griechische Nummern mit dem Praefix GR werden als EL behandelt, und nordirische Unternehmen (XI-Nummer, GB-Adresse) werden unterstuetzt.';
$_MODULE['<{vatnumber}prestashop>vatnumber_d17a37903c2ff7ec71c5bae45d1e5a22'] = 'Datum im Format JJJJ-MM-TT, oder leer, um alles zu pruefen. Nummern in der Warteschlange von Kunden ohne Adressaenderung und ohne Bestellung seit diesem Datum werden aus der Pruefwarteschlange entfernt. Nuetzlich nach dem Upgrade eines Shops mit jahrelangen alten Adressen. Entfernte Nummern werden einfach wieder live geprueft, falls ein solcher Kunde je zurueckkehrt.';
$_MODULE['<{vatnumber}prestashop>vatnumber_b9f5c797ebbf55adccdd8539a65a0241'] = 'Deaktiviert';
$_MODULE['<{vatnumber}prestashop>vatnumber_ac2f6a9cfa32070c4499f4879221058e'] = 'Deaktiviert (Standard): Kunden erhalten die USt-Befreiung sofort, auch solange ihre Nummer noch auf die Pruefung wartet. Aktiviert: Kunden zahlen weiter MwSt., bis VIES ihre Nummer bestaetigt hat. Aktiviert ist sicherer fuer Sie, deaktiviert ist kundenfreundlicher. Nur relevant, wenn die automatische Pruefung aktiv ist. Von VIES abgelehnte Nummern erhalten in keinem der beiden Modi die Befreiung.';
$_MODULE['<{vatnumber}prestashop>vatnumber_c3611ab7e05da6ec6a6d66098df71627'] = 'Jeder Lauf prueft %d Nummern. Um eine grosse Warteschlange schneller abzuarbeiten, haengen Sie &limit=%d an die URL an (das Maximum pro Lauf).';
$_MODULE['<{vatnumber}prestashop>vatnumber_00d23a76e43b46dae9ec7aa9dcbebb32'] = 'Aktiviert';
$_MODULE['<{vatnumber}prestashop>vatnumber_8aa92523f0a021be484f930bc2c1d452'] = 'Aktivierung fuegt ein einfaches Kontrollkaestchen fuer USt-Befreiungen hinzu. Nutzen Sie dies fuer USt-Befreiungen ohne USt-IdNr. Ein gesetztes Haekchen erkennen Sie an \'%s\' im Backoffice im USt-IdNr.-Feld unter Kunden -> Adressen.';
$_MODULE['<{vatnumber}prestashop>vatnumber_b25c4046a0e5c918765d51e10d709113'] = 'Geben Sie die vollstaendige Nummer inklusive des zweistelligen Laenderpraefixes ein, zum Beispiel %s. Leerzeichen, Punkte und Bindestriche sind kein Problem. Verwenden Sie EL oder GR fuer Griechenland und XI fuer Nordirland.';
$_MODULE['<{vatnumber}prestashop>vatnumber_2b094aac9f12f2abd921781ec657b254'] = 'Erst nach erfolgreicher Pruefung befreien';
$_MODULE['<{vatnumber}prestashop>vatnumber_aea517d5d463b0233b94bda69179abe0'] = 'Einstellung(en) konnten nicht gespeichert werden: %s';
$_MODULE['<{vatnumber}prestashop>vatnumber_aa5049a50d884b646c16f05475a37e82'] = 'Die USt-IdNr. konnte nicht geprueft werden. Bitte versuchen Sie es spaeter erneut.';
$_MODULE['<{vatnumber}prestashop>vatnumber_c547522aa7d85ddc28764bd5ea6ad860'] = 'Fuer 5 Minuten werden keine neuen VIES-Anfragen gesendet, damit die IP Ihres Servers nicht gedrosselt wird.';
