$_MODULE['<{vatnumber}prestashop>vatnumber_bc2285c91c86dfb3ed91e6682a69b43b'] = 'Das Startdatum fuer die Pruefung muss ein gueltiges Datum sein (JJJJ-MM-TT) oder leer, um alle Nummern zu pruefen.';
