$_MODULE['<{vatnumber}prestashop>vatnumber_2b1d586a3905df7dce992e1b92a011e5'] = 'Dieses Modul ergaenzt die Verarbeitung von USt-Befreiungen fuer verschiedene Steuergesetze.';
